function toggleAudioLesson(){if(!audioLessonQueue.length||audioLessonComplete){startAudioLesson(audioLessonId);return}if(audioLessonPaused){audioLessonPaused=false;if(audioResumeNeedsRestart){audioResumeNeedsRestart=false;playAudioLessonStep();updateAudioLessonStatus();return}if(audioEchoPending){clearTimeout(audioEchoTimer);audioEchoTimer=0;audioEchoPending=false;audioEchoReplay=true;playAudioLessonStep();updateAudioLessonStatus();return}if(kanjiAudioResumeFromStart){kanjiAudioResumeFromStart=false;playAudioLessonStep();updateAudioLessonStatus();return}if(window.speechSynthesis?.paused)window.speechSynthesis.resume();else if(audioPlayer&&!audioPlayer.ended&&audioPlayer.src){let result=audioPlayer.play();if(result&&typeof result.catch==='function')result.catch(()=>{audioLessonPaused=true;audioResumeNeedsRestart=true;speechToast('Audio was interrupted. Tap Resume to replay this sentence.');updateAudioLessonStatus()})}else playAudioLessonStep();updateAudioLessonStatus();return}audioLessonPaused=true;audioPlayer?.pause();window.speechSynthesis?.pause();updateAudioLessonStatus()}
function rewindKanjiAudio(){if(audioMode!=='kanji'||!audioLessonQueue.length||audioLessonIndex<=0)return;audioLessonIndex--;audioLessonComplete=false;audioEchoPending=false;audioEchoReplay=false;if(audioPlayer){audioPlayer.onended=null;audioPlayer.onerror=null;audioPlayer.pause()}kanjiAudioResumeFromStart=audioLessonPaused;if(audioLessonPaused){updateAudioLessonStatus();return}playAudioLessonStep()}
function restartAudioLesson(){startAudioLesson(audioLessonId)}
function setAudioMode(mode){if(!['conversation','full','kanji'].includes(mode)||mode===audioMode)return;audioMode=mode;selectAudioLesson(audioLessonId)}
function replayAudioLine(){if(audioMode!=='conversation')return;if(!audioLessonQueue.length){startAudioLesson(audioLessonId);return}audioEchoPending=false;audioEchoReplay=false;audioLessonPaused=false;audioLessonComplete=false;if(audioPlayer){audioPlayer.onended=null;audioPlayer.pause()}window.speechSynthesis?.cancel();playAudioLessonStep()}
function toggleAudioEcho(value){audioEchoEnabled=!!value;if(!audioEchoEnabled){clearTimeout(audioEchoTimer);audioEchoTimer=0;audioEchoPending=false;audioEchoReplay=false}updateAudioLessonStatus()}
function toggleAudioSpeed(value){audioSlowPlayback=!!value;if(audioPlayer&&!audioPlayer.paused)audioPlayer.playbackRate=audioSlowPlayback?.78:1;if(window.speechSynthesis?.speaking){window.speechSynthesis.cancel();playAudioLessonStep()}}
function toggleAudioContext(value){audioShowContext=!!value;updateAudioLessonStatus()}
function toggleAudioRomaji(value){audioShowRomaji=!!value;updateAudioLessonStatus()}
function selectAudioLesson(id){audioLessonQueue=[];audioLessonIndex=0;kanjiAudioResumeFromStart=false;audioLessonPaused=false;audioLessonComplete=false;audioEchoPending=false;audioEchoReplay=false;if(audioPlayer){audioPlayer.onended=null;audioPlayer.onerror=null;audioPlayer.pause()}window.speechSynthesis?.cancel();audioLessonId=Math.max(1,Math.min(LESSONS.length,Number(id)||1));render()}
function nav(v){if(v!=='kanji')kanjiContextCard=null;focusMode=FOCUS_ROUTES.includes(v);if(view==='n5'&&v!=='n5')stopN5Story();if(view==='audio'&&v!=='audio'){audioLessonQueue=[];audioLessonIndex=0;audioLessonPaused=false;audioLessonComplete=false;audioEchoPending=false;audioEchoReplay=false;if(audioPlayer){audioPlayer.onended=null;audioPlayer.onerror=null;audioPlayer.pause()}window.speechSynthesis?.cancel()}stopStrokeGuide();mobileMoreOpen=false;view=v;feedback='';builderChecked=false;strictNotice='';render();window.scrollTo(0,0)}
function goLesson(i,t='vocab'){i=Math.max(1,Math.min(LESSONS.length,Number(i)||1));if(state.strictMode&&i>strictUnlockedLesson()&&!strictLessonComplete(i)){strictNotice=`Finish Lesson ${strictUnlockedLesson()}'s checklist before opening later lessons.`;view='lessons';render();window.scrollTo(0,0);return}strictNotice='';if(state.strictMode&&i>lessonId&&i<=strictUnlockedLesson()&&strictLessonComplete(lessonId)&&state.completed[lessonId]!==true)recordLessonComplete(lessonId);lessonId=i;grammarFeedback='';tab=t;markLessonTabVisited(i,t);filter='all';search='';builder=[];builderChecked=false;feedback='';nav('lesson')}
function header(title,subtitle,eyebrow='YOUR LEARNING SPACE'){return `<div class="eyebrow">${eyebrow}</div><h1 class="title">${title}</h1>${state.showDescriptions?`<p class="subtitle page-description">${subtitle}</p>`:''}`}
function sectionGuide(text){return state.showGuides?`<aside class="section-guide" aria-label="How to use this section"><b>What to do</b><span>${esc(text)}</span></aside>`:''}
function applyGuideVisibility(){document.body.dataset.guideVisibility=state.showGuides?'shown':'hidden';document.body.dataset.descriptionVisibility=state.showDescriptions?'shown':'hidden'}
function setGuidePreference(show){state.showGuides=!!show;state.guideChoiceMade=true;save();applyGuideVisibility();let dialog=$('guide-choice');if(dialog?.open)dialog.close();dialog?.remove();render()}
function setDescriptionPreference(show){state.showDescriptions=!!show;state.guideChoiceMade=true;save();applyGuideVisibility();render()}
function setInitialGuidePreferences(show){state.showGuides=!!show;state.showDescriptions=!!show;state.guideChoiceMade=true;save();applyGuideVisibility();let dialog=$('guide-choice');if(dialog?.open)dialog.close();dialog?.remove();render()}
function promptGuidePreference(){if(state.guideChoiceMade||$('guide-choice'))return;let dialog=document.createElement('dialog');dialog.id='guide-choice';dialog.className='guide-dialog';dialog.setAttribute('aria-labelledby','guide-choice-title');dialog.setAttribute('aria-describedby','guide-choice-copy');dialog.innerHTML=`<div class="eyebrow">PERSONALIZE YOUR STUDY SPACE</div><h2 id="guide-choice-title">Keep short descriptions and “What to do” guidance?</h2><p id="guide-choice-copy">Hide tips and short descriptions to make more room while learning. You can change either choice any time in Settings.</p><div class="guide-dialog-actions"><button class="btn" type="button" onclick="setInitialGuidePreferences(false)">Hide permanently</button><button class="btn secondary" type="button" onclick="setInitialGuidePreferences(true)">Keep all</button></div>`;dialog.addEventListener('cancel',event=>{event.preventDefault();setInitialGuidePreferences(true)});document.body.append(dialog);dialog.showModal();dialog.querySelector('.guide-dialog-actions button')?.focus()}
const LESSON_SECTION_GUIDES={vocab:'Read each word and its example, play the audio, then mark words you can recall as learned.',grammar:'Study the pattern and worked example, then tap each sentence part to see how it contributes to the meaning.',dialogue:'Read the situation, listen to the exchange, and choose the reply that fits the conversation.',builder:'Use the English prompt to arrange Japanese words in a natural order, then check your sentence.',listening:'Play the Japanese sentence, choose its meaning, and reveal the transcript if you need a hint.',writing:'Read the English cue and type the Japanese word shown in this lesson’s vocabulary; then check it.',quiz:'Answer five mixed questions drawn from this lesson. Four correct answers complete the assessment.'};
function percent(a,b){return b?Math.round(100*a/b):0}
function due(r){return !r||(!r.mastered&&(!r.due||r.due<=today()))}function dueReviewCount(cards,reviews){return cards.filter(card=>{let r=reviews?.[card.id];return !!r&&typeof r==='object'&&!Array.isArray(r)&&typeof r.due==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(r.due)&&r.due<=today()}).length}
function streak(){let d=new Date(),n=0;for(let i=0;i<365;i++){let s=d.toLocaleDateString('en-CA');if(state.activity[s])n++;else if(i===0){d.setDate(d.getDate()-1);continue}else break;d.setDate(d.getDate()-1)}return n}
function strictChecklist(id){let l=LESSONS[id-1];if(!l)return[];let learned=l.vocab.filter(w=>state.learned[w.id]===true).length;return[
 {label:`Vocabulary marked learned (${learned}/${l.vocab.length})`,done:strictMilestoneDone(state,l,'vocabulary'),tab:strictChecklistTab('vocabulary')},
 {label:'Grammar sentence built correctly',done:strictMilestoneDone(state,l,'grammar'),tab:strictChecklistTab('grammar')},
 {label:'Conversation response correct',done:strictMilestoneDone(state,l,'conversation'),tab:strictChecklistTab('conversation')},
 {label:'Listening answer correct',done:strictMilestoneDone(state,l,'listening'),tab:strictChecklistTab('listening')},
 {label:'Writing answer typed correctly',done:strictMilestoneDone(state,l,'writing'),tab:strictChecklistTab('writing')},
 {label:'Assessment passed (4/5)',done:strictMilestoneDone(state,l,'assessment',ASSESSMENT_TYPES),tab:strictChecklistTab('assessment')}
]}
function strictLessonComplete(id){return strictChecklist(id).every(x=>x.done)}
function strictUnlockedLesson(){for(let i=1;i<=LESSONS.length;i++)if(!strictLessonComplete(i))return i;return LESSONS.length+1}
function strictCanNext(id){return id<LESSONS.length&&(!state.strictMode||(strictLessonComplete(id)&&id+1<=strictUnlockedLesson()))}
function setStrictMode(enabled){let next=!!enabled;if(next!==state.strictMode){quiz=null;quizAnswered=false;quizLesson=0}state.strictMode=next;strictNotice='';save();render()}
function recordLessonComplete(id){if(state.completed[id]!==true){state.completed[id]=true;reward(30)}}
function openChecklistStep(tab){selectLessonTab(tab);requestAnimationFrame(()=>window.scrollTo({top:0,behavior:'smooth'}))}
function strictChecklistPanel(id){let checks=strictChecklist(id),done=checks.filter(x=>x.done).length,available=checklistStepAvailability(checks);return `<div class="card strict-checklist"><div class="row between"><h2>Lesson checklist</h2><span class="pill">${done}/${checks.length} complete</span></div><ul>${checks.map((x,i)=>`<li class="${x.done?'done':''}"><button class="checklist-step" onclick="openChecklistStep('${x.tab}')" ${available[i]?'':'disabled'} aria-label="${esc(x.label)}${x.done?' · review':' · open next activity'}"><span aria-hidden="true">${x.done?'✓':'○'}</span><span>${esc(x.label)}</span><span class="checklist-action" aria-hidden="true">${x.done?'Review':'Open'} →</span></button></li>`).join('')}</ul></div>`}
function dashboard(){
 let total=LESSONS.reduce((s,l)=>s+l.vocab.length,0),learned=countKnownFlags(state.learned,LESSONS.flatMap(l=>l.vocab.map(w=>w.id))),completed=countCompletedLessons(LESSONS,state.completed,state.strictMode,strictLessonComplete),acc=percent(state.answers.filter(x=>x.correct===true).length,state.answers.length),dueCount=dueReviewCount(allCards(),state.reviews),nextLesson=state.strictMode?Math.min(LESSONS.length,strictUnlockedLesson()):Math.min(12,completed+1);
 let days=Array.from({length:14},(_,i)=>{let d=new Date();d.setDate(d.getDate()-(13-i));return {d:d.toLocaleDateString('en-CA'),n:state.activity[d.toLocaleDateString('en-CA')]||0}}),max=Math.max(1,...days.map(x=>x.n)),readiness=Math.round((completed/12*.45+learned/total*.25+countKnownFlags(state.kana,KANA.map(x=>x.ch))/KANA.length*.15+countKnownFlags(state.kanji,KANJI.map(x=>x.id))/KANJI.length*.15)*100);
 return `<div class="hero"><svg class="lesson-svg" viewBox="0 0 270 220" aria-hidden="true"><circle cx="175" cy="90" r="67" fill="#f4c7d2"/><path d="M45 175 Q130 85 240 175" fill="none" stroke="#333d6b" stroke-width="9" stroke-linecap="round"/><path d="M120 170 V65 M120 100 L80 70 M120 85 L155 45" stroke="#775f70" stroke-width="7" fill="none"/><g fill="#e89cb3"><circle cx="80" cy="70" r="18"/><circle cx="155" cy="45" r="19"/><circle cx="120" cy="65" r="16"/><circle cx="60" cy="110" r="10"/></g></svg>${header('Welcome back.','Continue your next lesson or browse the 12-part course.','SAKURA • BEGINNER ACADEMY')}<div class="row dashboard-actions"><button class="btn" onclick="resumeLastStudyLocation()">${lastStudyLocation?'Resume where you left off →':'Start learning →'}</button><button class="btn secondary" onclick="nav('lessons')">Browse lessons</button></div><label class="strict-toggle"><input type="checkbox" ${state.strictMode?'checked':''} onchange="setStrictMode(this.checked)"><span><b>Strict mode</b><small>Finish every lesson activity before advancing.</small></span></label></div><div class="grid dashboard-stats">${[['Lessons complete',completed+'/12'],['Words learned',learned+'/'+total],['Quiz accuracy',acc+'%'],['Reviews due',dueCount]].map(x=>`<div class="card"><div class="muted">${x[0]}</div><div class="stat">${x[1]}</div></div>`).join('')}</div><details class="card dashboard-activity"><summary><span>Study activity · ${streak()}-day streak</span><span class="pill">${state.xp} XP</span></summary><div class="row between"><span>Last 14 days · recorded learning actions</span><span class="pill">Daily goal ${state.goal} actions</span></div><div class="chart" aria-label="Daily activity chart">${days.map(x=>`<div title="${x.d}: ${x.n} actions" style="height:${Math.max(3,100*x.n/max)}%"></div>`).join('')}</div><p class="notice">Readiness estimate: ${readiness}% curriculum coverage, not a JLPT score or proficiency certification.</p></details>`
}
function lessonCards(){let unlocked=strictUnlockedLesson();return `<div class="grid">${LESSONS.map(l=>{let complete=state.strictMode?strictLessonComplete(l.id):state.completed[l.id]===true,locked=state.strictMode&&l.id>unlocked&&!complete,progress=complete?100:percent(l.vocab.filter(w=>state.learned[w.id]===true).length,l.vocab.length);return `<div class="card lesson-card"><div class="row between"><span class="lessonnum">LESSON ${String(l.id).padStart(2,'0')}</span>${complete?'✓ Completed':''}</div><h3>${esc(l.title)}</h3><div class="muted">${esc(l.description)}</div><div class="jp">${esc(l.jp)}</div><div class="progress"><div style="width:${progress}%"></div></div>${locked?`<p class="notice">Complete Lesson ${unlocked}'s checklist first.</p>`:''}<p><button class="btn small" ${locked?'disabled':''} onclick="goLesson(${l.id})">${locked?'🔒 Locked':'Open lesson →'}</button></p></div>`}).join('')}</div>`}
function lesson(){let l=LESSONS[lessonId-1],tabs=[['vocab','Vocabulary'],['grammar','Grammar lab'],['dialogue','Conversation'],['builder','Sentence builder'],['listening','Listening'],['writing','Writing'],['quiz','Assessment']],canNext=strictCanNext(lessonId),canComplete=!state.strictMode||strictLessonComplete(lessonId);markLessonTabVisited(lessonId,tab);return `<section class="lesson-focus-shell"><div class="lesson-toolbar row between"><button class="btn ghost small" onclick="lessonBackOrExit()">${focusMode?'← Exit focus':'← All lessons'}</button><span class="pill">${focusMode?`LESSON ${l.id} · ${tabs.find(x=>x[0]===tab)[1]}`:`LESSON ${l.id} / 12`}</span>${focusMode?'':`<button class="btn ghost small" aria-pressed="${focusMode}" onclick="toggleFocusMode()">⛶ Focus mode</button>`}</div><div class="lesson-overview">${header(esc(l.title),esc(l.description),'INTERACTIVE LESSON')}<div class="card"><div class="bigjp jp">${esc(l.jp)}</div><div>${esc(l.en)}</div><div class="row" style="margin-top:12px"><button class="btn secondary small" onclick="speak(LESSONS[lessonId-1].jp)">▶ Listen</button><button class="btn ghost small" onclick="romaji=!romaji;render()">${romaji?'Hide':'Show'} romaji</button></div></div></div><div class="lesson-tabbar"><div class="tabs" role="group" aria-label="Lesson sections; swipe horizontally to see all seven sections">${tabs.map(t=>{let status=lessonTabStatus(t[0],l,state,ASSESSMENT_TYPES),meta={'not-started':['Not started',''],'in-progress':['In progress','•'],complete:['Complete','✓'],'needs-review':['Needs review','!']}[status];return `<button class="tab status-${status} ${tab===t[0]?'active':''}" title="${meta[0]}" aria-label="${esc(t[1])}: ${meta[0]}" onclick="selectLessonTab('${t[0]}')">${t[1]}${meta[1]?`<span class="tab-status-mark" aria-hidden="true">${meta[1]}</span>`:''}</button>`}).join('')}</div><span class="tab-overflow-cue" aria-hidden="true">↔</span></div><div class="lesson-activity">${sectionGuide(LESSON_SECTION_GUIDES[tab])}${({vocab:vocabulary,grammar:grammar,dialogue:dialogue,builder:sentenceBuilder,listening:listening,writing:writing,quiz:assessment})[tab](l)}</div><div class="lesson-extra">${state.strictMode?strictChecklistPanel(lessonId):''}<div class="divider"></div><div class="row between"><button class="btn secondary" onclick="goLesson(${Math.max(1,lessonId-1)})" ${lessonId===1?'disabled':''}>← Previous</button><button class="btn" onclick="completeLesson()" ${canComplete?'':'disabled'}>${state.completed[lessonId]===true?'✓ Lesson completed':'Mark lesson complete'}</button><button class="btn secondary" onclick="goLesson(${Math.min(12,lessonId+1)})" ${canNext?'':'disabled'}>Next →</button></div>${state.strictMode&&!canNext&&lessonId<12?`<p class="notice">Complete every item in the checklist to unlock Next.</p>`:''}</div></section>`}
function completeLesson(){if(state.strictMode&&!strictLessonComplete(lessonId)){feedback='Complete every strict mode checklist item before marking this lesson complete.';render();return}recordLessonComplete(lessonId);render()}
function vocabulary(l){let cats=[...new Set(l.vocab.map(w=>w.category))],list=l.vocab.filter(w=>(filter==='all'||w.category===filter)&&(w.jp.includes(search)||w.en.toLowerCase().includes(search.toLowerCase())));return `<div class="row between"><input class="field" aria-label="Search vocabulary" placeholder="Search words" value="${esc(search)}" oninput="search=this.value;updateWords()"><select class="field" aria-label="Vocabulary category" onchange="filter=this.value;updateWords()"><option value="all">All categories</option>${cats.map(c=>`<option ${filter===c?'selected':''}>${c}</option>`).join('')}</select></div><div id="wordList">${wordCards(list)}</div>`}
function updateWords(){let l=LESSONS[lessonId-1];$('wordList').innerHTML=wordCards(l.vocab.filter(w=>(filter==='all'||w.category===filter)&&(w.jp.includes(search)||w.en.toLowerCase().includes(search.toLowerCase()))))}
function wordCards(list){return `<div class="wordgrid" style="margin-top:16px">${list.map(w=>`<div class="word"><div class="row between"><span class="muted">${esc(w.category)}</span><button class="btn ghost small" aria-label="Hear ${esc(w.jp)}" onclick="speak('${w.jp}',{reading:'${w.reading||w.jp}',displayText:'${w.jp}'})">▶ Word</button></div><div class="jp">${esc(w.jp)}</div>${romaji?`<small>${esc(w.romaji)}</small>`:''}<p><b>${esc(w.en)}</b></p><div class="row between"><p class="notice jp">${esc(w.example)}</p><div class="row"><button class="btn ghost small" aria-label="Play example sentence" onclick="speak('${w.example}')">▶ Listen</button></div></div><p class="notice">${esc(w.exampleEn)}</p><details class="usage-note"><summary>How and when to use it</summary><p>${esc(WORD_GUIDANCE[w.jp]||'Use this word in the situations shown by the example. Notice its category and the particle or verb it appears with.')}</p></details><button class="btn small ${state.learned[w.id]===true?'secondary':''}" onclick="learn('${w.id}')">${state.learned[w.id]===true?'✓ Learned':'Mark learned'}</button></div>`).join('')}</div>`}
function learn(id){if(state.learned[id]!==true){state.learned[id]=true;rewardOnce('vocabulary:'+id,5)}else state.learned[id]=false;save();render()}
function grammar(l){let reviewed=new Set(Array.isArray(state.grammarParts[l.id])?state.grammarParts[l.id]:[]).size;return `<div class="card"><span class="eyebrow">PATTERN & MEANING</span><h2>${esc(l.rule)}</h2><p>${esc(l.explain)}</p><h3 class="section">Worked example</h3><p class="jp">${esc(l.jp)}</p><p>${esc(l.en)}</p><div class="row"><button class="btn ghost small" onclick="speak('${l.jp}')" aria-label="Play complete worked example">▶ Hear full sentence</button></div><p class="muted">Tap each word or particle to see its role and complete this section (${reviewed}/${l.builder.length} explored).</p><div class="grammar-parts">${l.builder.map((x,i)=>`<button id="grammar-part-${i}" class="token" onclick="inspect(${i})">${esc(x)}</button>`).join('')}</div><div id="inspect" class="feedback" aria-live="polite">${esc(grammarFeedback||'These tiles form the worked example above. Tap one to see its role.')}</div><p class="notice"><b>Common mistake:</b> ${esc(l.mistake)}</p><button class="btn" onclick="selectLessonTab('builder')">Practice sentence structure →</button></div>`}
function inspect(i){let l=LESSONS[lessonId-1],x=l.builder[i],w=l.vocab.find(w=>w.jp===x);if(!Number.isInteger(i)||i<0||i>=l.builder.length)return;if(!Array.isArray(state.grammarParts[l.id]))state.grammarParts[l.id]=[];if(!state.grammarParts[l.id].includes(i))state.grammarParts[l.id].push(i);let reviewed=new Set(state.grammarParts[l.id]).size;grammarFeedback=x+' · '+(w?w.en:({'は':'topic marker (pronounced wa)','を':'direct-object marker','に':'destination / time / location marker','が':'subject marker','です':'polite copula','より':'comparison baseline','ください':'polite request','と':'quotation marker'}[x]||'Grammatical unit. Observe its position in the complete sentence.'))+` · ${reviewed}/${l.builder.length} parts explored`;save();render();$(`grammar-part-${i}`)?.focus()}
function dialogue(l){let answered=feedback.startsWith('Correct')||feedback.startsWith('Not quite');return `<div class="card"><h2>In context: a short exchange</h2>${l.dialogue.filter(d=>d.who==='A').map(d=>`<div class="feedback"><b>Speaker A</b><div class="jp jp-dialogue">${esc(d.jp)}</div><div>${esc(d.en)}</div><div class="row"><button class="btn ghost small" onclick="speak('${d.jp}')">▶ Listen</button></div></div>`).join('')}<h3>What is a natural response?</h3><p>Choose a polite reply that fits what Speaker A said.</p>${(l.responseOptions||[]).map((x,i)=>`<button class="option" ${answered?'disabled':''} onclick="dialogueAnswer(${i})">${esc(x)}</button>`).join('')}${answered?`<div class="feedback ${feedback.startsWith('Correct')?'good':'bad'}" aria-live="polite">${esc(feedback)}</div><div class="feedback"><b>Speaker B</b><div class="jp jp-dialogue">${esc(l.dialogue.find(d=>d.who==='B')?.jp||'')}</div><div>${esc(l.dialogue.find(d=>d.who==='B')?.en||'')}</div><div class="row"><button class="btn ghost small" onclick="speak('${l.dialogue.find(d=>d.who==='B')?.jp||''}')">▶ Listen</button></div></div>${feedback.startsWith('Not quite')?`<button class="btn secondary" onclick="feedback='';render()">Try another response</button>`:''}`:''}<p class="notice">Listen for a reply that fits the situation and keeps the conversation natural and polite.</p></div>`}
function dialogueAnswer(i){if(feedback.startsWith('Correct')||feedback.startsWith('Not quite'))return;let l=LESSONS[lessonId-1],correct=i===l.responseAnswer;feedback=correct?'Correct! That reply fits the situation.':'Not quite. Compare the choices with the natural reply below.';state.answers.push({lesson:lessonId,format:'dialogue',correct,date:today()});if(correct)rewardOnce('lesson:'+lessonId+':dialogue',5);save();render()}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}let shuffled=[];
function sentenceBuilder(l){if(!shuffled.length||shuffled.join('')!==l.builder.slice().sort().join(''))shuffled=shuffle(l.builder);return `<div class="card"><h2>Build the sentence</h2><p>Translate: <b>${esc(l.builderEn)}</b></p><div class="row"><button class="btn ghost small" onclick="speak('${l.jp}')" aria-label="Hear the model sentence">▶ Hear model sentence</button></div><div class="answer" aria-label="Constructed sentence">${builder.map((w,i)=>`<button class="token" onclick="builder.splice(${i},1);builderChecked=false;render()">${esc(w)} ×</button>`).join('')}</div><div class="grammar-parts">${shuffled.map((w,i)=>`<button class="token" ${builder.filter(x=>x===w).length>=shuffled.filter(x=>x===w).length?'disabled':''} onclick="builder.push(shuffled[${i}]);builderChecked=false;render()">${esc(w)}</button>`).join('')}</div><button class="btn" ${builderChecked?'disabled':''} onclick="checkBuilder()">Check sentence</button> <button class="btn secondary" onclick="builder=[];builderChecked=false;render()">Reset</button>${feedback?`<div class="feedback ${feedback.startsWith('Correct')?'good':'bad'}">${esc(feedback)}</div>`:''}</div>`}
function checkBuilder(){if(builderChecked)return;builderChecked=true;let l=LESSONS[lessonId-1],ok=builder.join('|')===l.builder.join('|');feedback=ok?'Correct! '+l.builderEn:'Not quite. Check particle placement and word order. Model: '+l.builder.join(' ');state.answers.push({lesson:lessonId,format:'ordering',correct:ok,date:today()});if(ok)rewardOnce('lesson:'+lessonId+':ordering',10);save();render()}
function listening(l){let answered=feedback.startsWith('Correct.')||feedback.startsWith('Incorrect.');return `<div class="card"><h2>Listen and understand</h2><p>Press play, then choose the meaning. If speech is unsupported, reveal the Japanese transcript.</p><div class="row"><button class="btn" onclick="speak(LESSONS[lessonId-1].jp)">▶ Play Japanese</button><button class="btn secondary" onclick="$('transcript').classList.toggle('hidden')">Show / hide transcript</button></div><p id="transcript" class="jp jp-prompt hidden">${esc(l.jp)}</p>${shuffle([l.en,'I do not understand.','Please come here.']).map(x=>`<button class="option" ${answered?'disabled':''} onclick="listenAnswer(this.textContent)">${esc(x)}</button>`).join('')}${answered?`<div class="feedback ${feedback.startsWith('Correct')?'good':'bad'}" aria-live="polite">${esc(feedback)}</div><button class="btn secondary" onclick="feedback='';render()">Try another answer</button>`:''}</div>`}
function listenAnswer(x){if(feedback.startsWith('Correct.')||feedback.startsWith('Incorrect.'))return;let ok=x===LESSONS[lessonId-1].en;feedback=(ok?'Correct.':'Incorrect.')+' '+LESSONS[lessonId-1].jp+' = '+LESSONS[lessonId-1].en;state.answers.push({lesson:lessonId,format:'listening',correct:ok,date:today()});if(ok)rewardOnce('lesson:'+lessonId+':listening',8);save();render()}
function norm(s){return String(s).normalize('NFKC').toLowerCase().replace(/[\s\u3000。、！？!?.,'"「」]/g,'').replace(/ー/g,'ー')}
function writing(l){let w=l.vocab[0],answered=feedback.startsWith('Correct')||feedback.startsWith('Expected:');return `<div class="card"><h2>Typing and writing studio</h2><p>Type the Japanese for <b>${esc(w.en)}</b>. Hiragana or katakana as shown in the vocabulary list.</p><input id="writeInput" class="field" lang="ja" autocomplete="off" placeholder="Type Japanese here" ${answered?'disabled':''}><button class="btn" ${answered?'disabled':''} onclick="checkWriting()">Check</button>${feedback?`<div class="feedback ${feedback.startsWith('Correct')?'good':'bad'}" aria-live="polite">${esc(feedback)}</div>`:''}${answered?`<button class="btn secondary" onclick="feedback='';render()">Try again</button>`:''}<div class="divider"></div><h3>Character handwriting practice</h3><p class="muted">For a visual model, animated stroke order, and a dedicated canvas for hiragana, katakana, or beginner kanji, open guided character practice. Your typed answer above remains part of this lesson.</p><button class="btn secondary" onclick="nav('handwriting')">✎ Open character writing practice</button></div>`}
function checkWriting(){if(feedback.startsWith('Correct')||feedback.startsWith('Expected:'))return;let w=LESSONS[lessonId-1].vocab[0],v=$('writeInput').value,ok=norm(v)===norm(w.jp);feedback=ok?'Correct!':'Expected: '+w.jp+' ('+w.en+')';state.answers.push({lesson:lessonId,format:'typing',correct:ok,date:today()});if(ok)rewardOnce('lesson:'+lessonId+':writing',8);save();render()}


function practicePool(){return practiceScript==='Kanji'?KANJI.map(k=>({ch:k.ch,r:k.kun.split('・')[0],meaning:k.meaning,script:'Kanji',id:k.id})):KANA.filter(k=>k.script===practiceScript&&!k.extra).map((k,i)=>({ch:k.ch,r:k.r,meaning:k.r,script:practiceScript,id:practiceScript.slice(0,1)+i}))}
// Stroke paths from KanjiVG, © Ulrich Apel and contributors, CC BY-SA 3.0.
// Source: https://kanjivg.tagaini.net/ ; bundled paths are shared under CC BY-SA 3.0.

let strokeTimer=null,strokeStep=0;
function kanjiStrokePaths(ch){return STROKES[ch]||globalThis.SAKURA_KANJI_SUPPLEMENTAL?.[ch]?.strokePaths||[]}
function strokeOrderSvg(ch,upto=0){let a=kanjiStrokePaths(ch);return `<svg viewBox="0 0 109 109" role="img" aria-label="Stroke order for ${ch}" style="width:min(100%,320px);height:auto;background:#fff;border:1px solid var(--line);border-radius:14px"><path d="M4 4h101v101H4zM4 54.5h101M54.5 4v101" fill="none" stroke="#eee8e7" stroke-width="0.8"/>${a.map((d,i)=>`<path d="${d}" fill="none" stroke="${i<upto?'#bd637c':'#c7c5cc'}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" opacity="${i<upto?'1':'.35'}"/>${i<upto?`<text x="${strokeLabel(i)[0]}" y="${strokeLabel(i)[1]}" font-size="9" font-weight="700" fill="#252e59">${i+1}</text>`:''}`).join('')}</svg>`}
function strokeLabel(i){return [[8,15],[90,17],[8,99],[92,99],[8,56],[96,56],[51,11],[51,103],[16,35],[95,35]][i%10]}
function showStrokeStep(n){let ch=practicePool()[practiceIndex%practicePool().length].ch;strokeStep=Math.max(0,Math.min(STROKES[ch].length,n));let v=$('strokeGuide');if(v)v.innerHTML=strokeOrderSvg(ch,strokeStep);let l=$('strokeStepLabel');if(l)l.textContent=strokeStep===0?'Ready · '+STROKES[ch].length+' strokes':`Stroke ${strokeStep} of ${STROKES[ch].length}`}
function playKanjiStrokeOrder(ch){let paths=kanjiStrokePaths(ch);if(!paths.length)return;stopStrokeGuide();strokeStep=0;const draw=()=>{let guide=$('kanjiStrokeGuide'),label=$('kanjiStrokeStepLabel');if(guide)guide.innerHTML=strokeOrderSvg(ch,strokeStep);if(label)label.textContent=strokeStep===0?'Starting · '+paths.length+' strokes':`Stroke ${strokeStep} of ${paths.length}`};draw();strokeTimer=setInterval(()=>{if(strokeStep>=paths.length){stopStrokeGuide();return}strokeStep++;draw()},850)}
function stopStrokeGuide(){if(strokeTimer){clearInterval(strokeTimer);strokeTimer=null}let b=$('strokePlay');if(b)b.textContent='↺ Replay order'}
function playStrokeOrder(){stopStrokeGuide();showStrokeStep(0);let ch=practicePool()[practiceIndex%practicePool().length].ch;let b=$('strokePlay');if(b)b.textContent='❚❚ Playing';strokeTimer=setInterval(()=>{if(strokeStep>=STROKES[ch].length){stopStrokeGuide();return}showStrokeStep(strokeStep+1)},850)}
function strokePrev(){stopStrokeGuide();showStrokeStep(strokeStep-1)}function strokeNext(){stopStrokeGuide();showStrokeStep(strokeStep+1)}
function handwriting(){let pool=practicePool(),item=pool[practiceIndex%pool.length],done=state.handwriting||{};return `${header('Handwriting practice','Learn each character in stages: hiragana, katakana, then 84 beginner kanji. Draw with your finger, mouse, or stylus.','WRITE JAPANESE')}<div class="row handwriting-script-tabs"><button class="btn ${practiceScript==='Hiragana'?'':'secondary'}" onclick="setPracticeScript('Hiragana')">Hiragana</button><button class="btn ${practiceScript==='Katakana'?'':'secondary'}" onclick="setPracticeScript('Katakana')">Katakana</button><button class="btn ${practiceScript==='Kanji'?'':'secondary'}" onclick="setPracticeScript('Kanji')">Beginner kanji</button><span class="pill">${countKnownFlags(done,practicePool().map(x=>practiceScript+':'+x.id))} practiced</span></div><div class="card handwriting-card" style="margin-top:18px"><div class="row between"><div><div class="eyebrow">${practiceScript} · ${practiceIndex%pool.length+1} of ${pool.length}</div><div class="bigjp jp practice-model">${item.ch}</div><b>${esc(item.r)} · ${esc(item.meaning)}</b></div><div class="notice">Reference character<br><span class="jp practice-reference-char">${item.ch}</span></div></div><p class="notice practice-hint">Trace the model, then try writing it from memory. </p><div class="practice-workspace"><div class="card stroke-card" style="margin:16px 0"><div class="row between"><div><h3 style="margin:0">Correct stroke order</h3><p id="strokeStepLabel" class="notice">Ready · ${STROKES[item.ch].length} strokes</p></div><div class="row"><button id="strokePlay" class="btn" aria-label="Replay correct stroke order" onclick="playStrokeOrder()">↺ Replay order</button><button class="btn secondary" onclick="strokePrev()">← Step</button><button class="btn secondary" onclick="strokeNext()">Step →</button></div></div><div id="strokeGuide" style="text-align:center;margin:10px 0">${strokeOrderSvg(item.ch)}</div><p class="notice">Strokes appear one at a time in numbered order. Source: <a href="https://kanjivg.tagaini.net/" target="_blank" rel="noopener">KanjiVG</a>, © Ulrich Apel and contributors, CC BY-SA 3.0. Bundled diagrams are shared under CC BY-SA 3.0.</p></div><canvas id="practiceDraw" width=900 height=500 aria-label="Handwriting practice canvas" style="display:block;width:100%;height:clamp(300px,55vh,500px);border:1px solid #e9c4cf;border-radius:16px;background-color:#fff;background-image:linear-gradient(90deg,transparent 49.85%,#f3e8ec 50%,transparent 50.15%),linear-gradient(transparent 49.85%,#f3e8ec 50%,transparent 50.15%);touch-action:none;"></canvas></div><div class="row practice-actions" style="margin-top:14px"><button class="btn secondary" onclick="undoPractice()" ${practiceUndo.length?'':'disabled'}>Undo stroke</button><button class="btn ghost" onclick="clearPractice()">Clear</button><button class="btn secondary" onclick="speak('${item.ch}')">▶ Listen</button><span style="flex:1"></span><button class="btn secondary" onclick="stepPractice(-1)">← Previous</button><button class="btn" onclick="finishPractice('${practiceScript}:${item.id}')">Mark practiced · Next →</button></div><p class="notice">Progress saves on this device. ${practiceIndex+1>=pool.length?'You reached the end of this set; next wraps to the first character.':''}</p></div>`}
function setupPracticeCanvas(){let c=$('practiceDraw');if(!c)return;let ctx=c.getContext('2d'),drawing=false,points=[];ctx.strokeStyle='#252e59';ctx.lineWidth=9;ctx.lineCap='round';ctx.lineJoin='round';const pos=e=>{let r=c.getBoundingClientRect();return{x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height}};c.onpointerdown=e=>{drawing=true;points=[];c.setPointerCapture(e.pointerId);let p=pos(e);points.push(p);ctx.beginPath();ctx.moveTo(p.x,p.y)};c.onpointermove=e=>{if(!drawing)return;let p=pos(e);points.push(p);ctx.lineTo(p.x,p.y);ctx.stroke()};c.onpointerup=c.onpointercancel=()=>{if(drawing&&points.length){practiceUndo.push(points);drawing=false}}}
function redrawPractice(){let c=$('practiceDraw');if(!c)return;let ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);for(let stroke of practiceUndo){ctx.beginPath();stroke.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke()}}
function undoPractice(){practiceUndo.pop();redrawPractice();render()}function clearPractice(){practiceUndo=[];redrawPractice();render()}function clearPracticeForNext(){practiceUndo=[]}
function setPracticeScript(script){stopStrokeGuide();practiceScript=script;practiceIndex=0;strokeStep=0;practiceUndo=[];render()}function stepPractice(n){stopStrokeGuide();strokeStep=0;practiceIndex=(practiceIndex+n+practicePool().length)%practicePool().length;practiceUndo=[];render()}function finishPractice(key){stopStrokeGuide();strokeStep=0;state.handwriting=state.handwriting||{};if(!state.handwriting[key]){state.handwriting[key]=true;rewardOnce('handwriting:'+key,2)}practiceIndex=(practiceIndex+1)%practicePool().length;practiceUndo=[];render()}
function newAssessment(l){let words=shuffle(assessmentWordPool(l,state.learned));if(words.length<2)return null;return {questionTypes:shuffle([...ASSESSMENT_TYPES]),wordIds:words.slice(0,2).map(w=>w.id),results:[],passed:false}}
function assessmentRun(l){let existing=state.assessments[l.id],run=ensureAssessmentRun(existing,l,ASSESSMENT_TYPES,newAssessment,state.learned);if(run!==existing){state.assessments[l.id]=run;save()}return run}
function makeQuiz(l){let run=assessmentRun(l),index=run.results.length,type=run.questionTypes[index],words=id=>l.vocab.find(w=>w.id===id)||l.vocab[0],chosen=(type==='writing'?words(run.wordIds[1]):words(run.wordIds[0])),options=(correct,candidates)=>shuffle([correct,...shuffle([...new Set(candidates.filter(x=>x!==correct))]).slice(0,3)]);quiz={type,index,typed:false,options:[],jp:'',prompt:'',correct:'',explanation:''};if(type==='vocabulary'){quiz.jp=chosen.jp;quiz.prompt=`What does ${chosen.jp} mean?`;quiz.correct=chosen.en;quiz.options=options(quiz.correct,assessmentOptionCandidates(l,type,state.learned));quiz.explanation=`${chosen.jp} = ${chosen.en}.`}else if(type==='grammar'){quiz.prompt=`Which Japanese sentence means “${l.builderEn}”?`;quiz.correct=l.builder.join(' ');quiz.options=options(quiz.correct,assessmentOptionCandidates(l,type,state.learned));quiz.explanation=`${quiz.correct} = ${l.builderEn}.`}else if(type==='dialogue'){let line=l.dialogue.find(d=>d.who==='A')||l.dialogue[0];quiz.jp=line.jp;quiz.prompt='What does Speaker A say?';quiz.correct=line.en;quiz.options=options(quiz.correct,assessmentOptionCandidates(l,type,state.learned));quiz.explanation=`${line.jp} = ${line.en}.`}else if(type==='listening'){quiz.jp=l.jp;quiz.prompt='Listen to the Japanese, then choose its meaning.';quiz.correct=l.en;quiz.options=options(quiz.correct,assessmentOptionCandidates(l,type,state.learned));quiz.explanation=`${l.jp} = ${l.en}.`}else{quiz.prompt=`Type the Japanese for “${chosen.en}”.`;quiz.correct=chosen.jp;quiz.typed=true;quiz.jp=chosen.jp;quiz.explanation=`${chosen.jp} = ${chosen.en}.`}quizAnswered=false;quizLesson=l.id;showQuizText=false;feedback='';return quiz}
function retryAssessment(id){let l=LESSONS[id-1];if(!l)return;state.assessments[id]=newAssessment(l);quiz=null;quizAnswered=false;quizLesson=id;feedback='';save();makeQuiz(l);render()}
function assessment(l){let pool=assessmentWordPool(l,state.learned);if(pool.length<2)return `<div class="card"><div class="eyebrow">ASSESSMENT LOCKED</div><h2>Study the lesson vocabulary first</h2><p>Mark at least two words in this lesson as learned before starting the assessment. Vocabulary questions will use words you have studied.</p><button class="btn" onclick="selectLessonTab('vocab')">Review vocabulary →</button></div>`;let run=assessmentRun(l),score=run.results.filter(Boolean).length;if(run.passed)return `<div class="card"><div class="eyebrow">ASSESSMENT PASSED</div><h2>Lesson assessment complete</h2><div class="stat">${score} / 5</div><p>You passed with at least 4 correct answers across vocabulary, grammar, dialogue, listening, and writing.</p></div>`;if(run.results.length>=5)return `<div class="card"><div class="eyebrow">ASSESSMENT RESULT</div><h2>Try the assessment again</h2><div class="stat">${score} / 5</div><p>You need 4 correct answers to pass. Review the lesson and try a fresh set.</p><button class="btn" onclick="retryAssessment(${l.id})">Retry assessment</button></div>`;if(!quiz||quizLesson!==l.id||(quiz.index!==run.results.length&&!(quizAnswered&&quiz.index+1===run.results.length)))makeQuiz(l);let q=quiz,number=q.index+1,body=q.type==='listening'?`<div class="row"><button class="btn" onclick="speak('${q.jp}')">▶ Play Japanese</button><button class="btn secondary" onclick="showQuizText=!showQuizText;render()">${showQuizText?'Hide':'Show'} text</button></div>${showQuizText?`<p class="jp jp-dialogue">${esc(q.jp)}</p>`:''}${q.options.map(x=>`<button class="option" ${quizAnswered?'disabled':''} onclick="checkQuiz(this.textContent)">${esc(x)}</button>`).join('')}`:q.typed?`<p>${esc(q.prompt)}</p><input class="field" id="quizInput" lang="ja" autocomplete="off" ${quizAnswered?'disabled':''}><button class="btn" ${quizAnswered?'disabled':''} onclick="checkQuiz($('quizInput').value,true)">Check</button>`:`<p>${esc(q.prompt)}</p>${q.type==='dialogue'?`<p class="jp jp-prompt">${esc(q.jp)}</p>`:''}${q.options.map(x=>`<button class="option ${q.type==='grammar'?'jp':''}" ${quizAnswered?'disabled':''} onclick="checkQuiz(this.textContent)">${esc(x)}</button>`).join('')}`;return `<div class="card"><div class="row between"><h2>Lesson assessment</h2><span class="pill">Question ${number} of 5 · ${score} correct</span></div><p>Five questions cover vocabulary, grammar, dialogue, listening, and typed Japanese. You need at least four correct answers to pass.</p><span class="pill">${({vocabulary:'Vocabulary · Japanese → English',grammar:'Grammar · sentence meaning',dialogue:'Dialogue · comprehension',listening:'Listening · comprehension',writing:'Writing · type Japanese'})[q.type]}</span>${q.type==='listening'?`<p>${esc(q.prompt)}</p>`:''}${body}${feedback?`<div class="feedback ${feedback.startsWith('Correct')?'good':'bad'}" aria-live="polite">${esc(feedback)}</div>`:''}${run.results.length<5?`<button class="btn secondary" ${quizAnswered?'':'disabled'} onclick="makeQuiz(LESSONS[lessonId-1]);render()">Next question →</button>`:''}</div>`}
function checkQuiz(v,typed=false){if(quizAnswered||quizLesson!==lessonId||!quiz)return;let run=assessmentRun(LESSONS[lessonId-1]);if(quiz.index!==run.results.length)return;let ok=quiz.typed?typed&&norm(v)===norm(quiz.correct):!typed&&String(v)===quiz.correct;quizAnswered=true;feedback=(ok?'Correct! ':'Not quite. ')+quiz.explanation;state.answers.push({lesson:lessonId,format:'assessment-'+quiz.type,correct:ok,date:today()});run.results.push(ok);if(run.results.length===5)run.passed=run.results.filter(Boolean).length>=4;if(ok)reward(10);save();render()}
function allCards(){let lessonWords=LESSONS.flatMap(l=>l.vocab);let lessonIds=new Set(lessonWords.map(w=>w.jp+'|'+norm(w.en)));let n5=N5_VOCAB.filter(w=>!lessonIds.has(w.word+'|'+norm(w.meanings?.[0]||''))).map(w=>({id:'n5-'+w.id,jp:w.reading||w.word,kanji:/[\u4e00-\u9fff]/.test(w.word)?w.word:'',reading:w.reading||w.word,en:w.meanings.join('; '),category:'N5 vocabulary',romaji:w.romaji,example:w.examples?.[0]?.ja||w.word,exampleEn:w.examples?.[0]?.en||w.meanings[0]}));return lessonWords.concat(n5)}
function reviewCard(id,quality){let old=state.reviews[id]||{ease:2.5,interval:0,reps:0,history:[]};let r={...old};if(quality<3){r.reps=0;r.interval=1}else{r.interval=r.reps===0?1:r.reps===1?6:Math.max(1,Math.round(r.interval*r.ease));r.reps++}r.ease=Math.max(1.3,r.ease+(0.1-(5-quality)*(0.08+(5-quality)*0.02)));let d=new Date();d.setDate(d.getDate()+r.interval);r.due=d.toLocaleDateString('en-CA');r.history=[...(r.history||[]).slice(-99),{date:today(),quality}];state.reviews[id]=r;if(quality>=3){state.learned[id]=true;rewardOnce('review:'+id+':'+today(),5)}else activity();save();flashBack=false;render()}
function nextStudyCard(id){state.reviews[id]={...(state.reviews[id]||{}),mastered:true};state.learned[id]=true;rewardOnce('review:'+id+':'+today(),5);save();flashBack=false;render()}
function flashCardFront(w){return w.kanji||w.jp}
function flashCardReading(w){return w.kanji?w.reading:w.jp}
function flashCardFace(w){if(!flashBack)return `<div class="jp">${esc(flashCardFront(w))}</div><small>${w.kanji?'N5 kanji · tap to reveal reading':'Tap or press Enter to reveal meaning'}</small>`;return `<div class="stat">${esc(w.en)}</div><div class="jp">${esc(flashCardReading(w))}</div>${w.kanji?'<small>N5 kanji reading</small>':''}`}
function flashcards(){let cards=allCards().filter(w=>due(state.reviews[w.id]));if(!cards.length)return `${header('Study','No cards to practice right now. Saved cards return tomorrow or later.','STUDY LIST')}<button class="btn" onclick="nav('lessons')">Browse lessons</button>`;let w=cards[flashIndex%cards.length];return `${header('Study','Recognize the N5 kanji spelling. Tap to reveal its kana reading and meaning. Kana-only lesson words remain in their original spelling.','STUDY LIST')}<p class="pill">${cards.length} cards ready · Card ${flashIndex%cards.length+1}</p><div class="flash" role="button" tabindex="0" onclick="flashBack=!flashBack;render()" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();flashBack=!flashBack;render()}"><div>${flashCardFace(w)}</div></div><div class="row" style="justify-content:center"><button class="btn secondary" onclick="speak('${w.jp}',{reading:'${w.reading||w.jp}',displayText:'${w.jp}'})">▶ Hear</button>${flashBack?`<button class="btn secondary" onclick="nextStudyCard('${w.id}')">Next →</button><button class="btn" onclick="studyCard('${w.id}')">Add to Study</button>`:''}</div><p class="notice">Study cards return tomorrow for your next review. Saved progress stays on this device unless exported.</p>`}
function studyCard(id){reviewCard(id,4)}
function setKanaTab(next){stopStrokeGuide();kanaTab=next;if(next==='Hiragana'||next==='Katakana'){kanaScript=next;kanaSelectedCharacter=''}else kanaSelectedCharacter='';render()}
function kanaPage(){let list=KANA.filter(x=>x.script===kanaScript&&(kanaExtra==='all'||(kanaExtra==='basic'?!x.extra:kanaExtra==='modified'?x.extra&&!x.combo:x.combo)));let tabs=['Hiragana','Katakana','Challenge'];return `${header('Kana masterclass','Learn hiragana, katakana, voiced sounds and combinations. Tap any symbol to hear it.','JAPANESE WRITING')}<div class="kana-mode-tabs" role="tablist" aria-label="Kana study mode">${tabs.map(name=>`<button class="kana-mode-tab ${kanaTab===name?'active':''}" role="tab" aria-selected="${kanaTab===name}" onclick="setKanaTab('${name}')">${name}</button>`).join('')}</div>${sectionGuide(kanaTab==='Challenge'?'Start a question, identify the character’s sound, and use the timed round to check your recognition speed.':'Choose a character group, tap a symbol to hear its sound, and repeat it aloud before moving to the next one.')}
${kanaTab==='Challenge'?`<section class="card kana-challenge" role="tabpanel"><h2>Recognition challenge</h2><p class="muted">Read a ${kanaScript.toLowerCase()} character and choose its sound.</p><button class="btn" onclick="newKanaQuiz()">${kanaQuiz?'New question':'Start quiz'}</button>${kanaQuiz?`<div class="bigjp jp">${kanaQuiz.ch}</div><p>Choose the reading</p>${kanaQuiz.options.map(x=>`<button class="btn secondary" style="margin:4px" onclick="kanaAnswer('${x}')">${x}</button>`).join('')}`:''}${feedback?`<div class="feedback">${esc(feedback)}</div>`:''}<p class="notice">Timed challenge: <button class="btn ghost small" onclick="startTimer()">Start 60 seconds</button> <span id="timerLabel">${challengeEnd?'Challenge active':'Not started'}</span> · Correct: ${challengeScore}</p></section>`:`<div class="row kana-filters"><label class="sr-only" for="kanaFilter">Character group</label><select id="kanaFilter" class="field" onchange="kanaExtra=this.value;render()"><option value="basic" ${kanaExtra==='basic'?'selected':''}>Basic</option><option value="modified" ${kanaExtra==='modified'?'selected':''}>Dakuten / handakuten</option><option value="combo" ${kanaExtra==='combo'?'selected':''}>Combination sounds</option><option value="all" ${kanaExtra==='all'?'selected':''}>All</option></select></div>${kanaSelectedCharacter&&STROKES[kanaSelectedCharacter]?`<section class="card kana-stroke-card" aria-label="Selected kana stroke order"><div class="row between"><h2>${kanaSelectedCharacter} · ${KANA.find(x=>x.ch===kanaSelectedCharacter)?.r||''}</h2><button class="btn ghost small" onclick="playKanjiStrokeOrder('${kanaSelectedCharacter}')">↺ Replay order</button></div><div id="kanjiStrokeGuide" class="kanji-stroke-guide">${strokeOrderSvg(kanaSelectedCharacter)}</div><p id="kanjiStrokeStepLabel" class="notice" aria-live="polite">${STROKES[kanaSelectedCharacter].length} strokes · playing</p></section>`:''}<div class="kana-grid" style="margin:20px 0">${list.map(x=>`<button class="kana" aria-pressed="${kanaSelectedCharacter===x.ch}" onclick="kanaPick('${x.ch}')"><strong>${x.ch}</strong>${romaji?`<small>${x.r}</small>`:''}${state.kana[x.ch]===true?' <small>✓</small>':''}</button>`).join('')}</div>`}`}

function kanaPick(ch){let k=KANA.find(x=>x.ch===ch);stopStrokeGuide();kanaSelectedCharacter=ch;if(!state.kana[ch]){state.kana[ch]=true;rewardOnce('kana:'+ch,2)}feedback=ch+' is read '+k.r+'. Practice its shape and sound.';speak(ch);render()}
function revealKanaQuizQuestion(){let prompt=document.querySelector('.kana-challenge .bigjp');if(!prompt)return;let behavior=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth';prompt.scrollIntoView({block:'start',behavior})}
function newKanaQuiz(){let pool=KANA.filter(x=>x.script===kanaScript&&!x.extra),k=pool[Math.floor(Math.random()*pool.length)];kanaQuiz={ch:k.ch,r:k.r,options:shuffle([k.r,...shuffle([...new Set(pool.map(x=>x.r).filter(r=>r!==k.r))]).slice(0,3)])};feedback='';render();requestAnimationFrame(revealKanaQuizQuestion)}
function kanaAnswer(r){let ok=r===kanaQuiz.r;feedback=ok?'Correct! '+kanaQuiz.ch+' = '+r:'Incorrect. '+kanaQuiz.ch+' = '+kanaQuiz.r;if(ok){if(!state.kana[kanaQuiz.ch]){state.kana[kanaQuiz.ch]=true;rewardOnce('kana:'+kanaQuiz.ch,4)}if(challengeEnd&&Date.now()<challengeEnd)challengeScore++}else activity();save();if(challengeEnd&&Date.now()>challengeEnd){feedback+=' · Time is up! Score: '+challengeScore;challengeEnd=0}kanaQuiz=null;render()}
