function kanjiPage(){if(kanjiContextCard)return kanjiContextPage();let k=KANJI[kanjiIndex],studied=countKnownFlags(state.kanji,KANJI.map(x=>x.id)),saved=countKnownFlags(state.kanjiStudy,KANJI.map(x=>x.id));return `${kanjiTextReturn?'<button class="btn secondary kanji-return" aria-label="Return to previous study section" onclick="returnFromKanjiText()">← Return</button>':''}${header('Kanji explorer','84 beginner kanji with meanings, readings, examples, visual memory cues, and stroke order.','FOUNDATIONS')}${sectionGuide('Use the visual cue to remember the character. Add it to Study to revisit it later, or tap Next when you have studied it.')}<article class="card kanji-study-card"><div class="row between"><div><div class="eyebrow">CHARACTER ${kanjiIndex+1} OF ${KANJI.length}</div><div class="bigjp jp">${k.ch}</div></div><div><span class="pill">${studied}/${KANJI.length} studied</span><span class="pill">${saved} in Study</span></div></div><div class="kanji-stroke-details" aria-label="Animated stroke order"><h3>Stroke order</h3><div id="kanjiStrokeGuide" class="kanji-stroke-guide">${strokeOrderSvg(k.ch)}</div><p id="kanjiStrokeStepLabel" class="notice" aria-live="polite">${kanjiStrokePaths(k.ch).length} strokes · playing</p><button class="btn ghost small" onclick="playKanjiStrokeOrder('${k.ch}')">↺ Replay order</button></div><h2>${esc(k.meaning)}</h2><div class="kanji-memory"><b>Visual memory</b><p>${esc(k.memoryTip)}</p></div><p><b>On’yomi:</b> ${esc(k.on)}</p><p><b>Kun’yomi:</b> ${esc(k.kun)}</p><p><b>Example:</b> <span class="jp">${esc(k.example)}</span>${k.exampleReading&&k.exampleReading!==k.example?` <span class="muted">(<span lang="ja">${esc(k.exampleReading)}</span>)</span>`:''}</p><div class="row kanji-study-actions"><button class="btn secondary" aria-label="Hear example ${esc(k.example)} (${esc(k.exampleReading)})" onclick="speak('${k.example}',{reading:'${k.exampleReading}',displayText:'${k.example}'})">▶ Hear example</button><button class="btn" onclick="addKanjiToStudy()" ${state.kanjiStudy[k.id]===true?'disabled':''}>${state.kanjiStudy[k.id]===true?'✓ In Study':'Add to Study'}</button></div><p class="notice">Saved kanji stay marked in the character picker so you can open one and study it again.</p><div class="row between"><button class="btn secondary" onclick="moveKanji(-1)" ${kanjiIndex===0?'disabled':''}>← Previous</button><button class="btn" onclick="nextKanji()">${kanjiIndex===KANJI.length-1?'Finish & mark studied':'Next kanji →'}</button></div></article><details class="card kanji-picker"><summary>Choose a kanji to study again · ${saved} saved · ${studied}/${KANJI.length} studied</summary><p class="notice">Choose a saved kanji to revisit it. ☆ marks kanji in your Study list.</p><div class="kana-grid">${KANJI.map((x,i)=>`<button class="kana" aria-pressed="${i===kanjiIndex}" onclick="selectKanji(${i})"><strong>${x.ch}</strong><small>${state.kanjiStudy[x.id]===true?'☆ In Study · ':state.kanji[x.id]===true?'✓ Studied · ':''}${esc(x.meaning.split(' / ')[0])}</small></button>`).join('')}</div></details>`}
