async function importData(file){if(!file)return;try{if(file.size>2000000)throw Error('Backup too large');let d=JSON.parse(await file.text()),s=d.state;if(d.version!==1||!s||typeof s!=='object'||Array.isArray(s)||!Array.isArray(s.answers)||typeof s.xp!=='number')throw Error('Invalid backup structure');for(let k of ['reviews','learned','completed','activity','kana','kanji','handwriting'])if(!s[k]||typeof s[k]!=='object'||Array.isArray(s[k]))throw Error('Invalid '+k);if(s.assessments!==undefined&&(!s.assessments||typeof s.assessments!=='object'||Array.isArray(s.assessments)))throw Error('Invalid assessments');if(s.rewarded!==undefined&&(!s.rewarded||typeof s.rewarded!=='object'||Array.isArray(s.rewarded)))throw Error('Invalid rewarded');if(s.tabVisits!==undefined&&(!s.tabVisits||typeof s.tabVisits!=='object'||Array.isArray(s.tabVisits)))throw Error('Invalid tab visits');if(s.grammarParts!==undefined&&(!s.grammarParts||typeof s.grammarParts!=='object'||Array.isArray(s.grammarParts)))throw Error('Invalid grammar progress');if(s.strictMode!==undefined&&typeof s.strictMode!=='boolean')throw Error('Invalid strictMode');let settingsErrors=validateProgressBackupSettings(s),strictErrors=validateStrictProgressData(s),practiceErrors=validatePracticeProgressData(s);if(settingsErrors.length||strictErrors.length||practiceErrors.length)throw Error([...settingsErrors,...strictErrors,...practiceErrors].join(', '));if(!confirm('Replace all current progress with this backup?'))return;state={...fresh(),...s};state.grammarParts=sanitizeGrammarParts(state.grammarParts,LESSONS);sanitizePracticeProgressData(state);applyGuideVisibility();save();render();promptGuidePreference();alert('Backup imported.')}catch(e){alert('Import failed: '+e.message)}}
