function handleKanjiTextActivation(event){let target=event.target.closest?.('.kanji-tap-target');if(!target)return;if(event.type==='keydown'&&!['Enter',' '].includes(event.key))return;if(event.type==='click'&&event.button!==0)return;let index=target.dataset.kanjiIndex===undefined?null:Number(target.dataset.kanjiIndex);event.preventDefault();event.stopPropagation();openKanjiFromStudyText(index,target.dataset.kanjiChar||'',target.dataset.kanjiContext||'')}
